ORGS = {
    "shopping-seller": {"knowledge": "seller_faq_v3", "call_hours": (10, 18),
                         "handoff_keywords": ["환불 분쟁", "법적"], "max_retries": 2},
    "loan-outbound":   {"knowledge": "loan_terms_2026", "call_hours": (9, 20),
                         "handoff_keywords": ["민원", "녹음 거부"], "max_retries": 1},
}

def can_call(org, hour):
    start, end = ORGS[org]["call_hours"]
    return start <= hour < end

def needs_handoff(org, text):
    return any(k in text for k in ORGS[org]["handoff_keywords"])

print(can_call("shopping-seller", 19), can_call("loan-outbound", 19))  # False True
print(needs_handoff("loan-outbound", "이거 민원 넣을 거예요"))          # True

def wer(ref, hyp):
    r, h = ref.split(), hyp.split()
    d = [[0] * (len(h) + 1) for _ in range(len(r) + 1)]
    for i in range(len(r) + 1):
        d[i][0] = i
    for j in range(len(h) + 1):
        d[0][j] = j
    for i in range(1, len(r) + 1):
        for j in range(1, len(h) + 1):
            c = 0 if r[i - 1] == h[j - 1] else 1
            d[i][j] = min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + c)
    return d[len(r)][len(h)] / len(r)

print(f"WER = {wer('다음 달 오일 자동이체 해지해 주세요', '다음 달 오일 자동이체 해주세요'):.2f}")
# WER = 0.33
